input.text:
const h2 = document.querySelector('h2');
const sectionStack = h2.parentElement;
const cs = getComputedStyle(sectionStack);
JSON.stringify({rowGap: cs.rowGap, gap: cs.gap});

const buttons = Array.from(document.querySelectorAll('button'));
const findInBoutique = buttons.find(b => /find in boutique/i.test(b.textContent));
const triggers = buttons.filter(b => b !== findInBoutique);
const outerStack = findInBoutique?.parentElement;
function iconInfo(btn) {
  const svg = btn.querySelector('svg');
  return svg ? {viewBox: svg.getAttribute('viewBox'), innerHTML: svg.innerHTML.slice(0,80)} : null;
}
JSON.stringify({
  outerGap: outerStack ? getComputedStyle(outerStack).rowGap : null,
  findInBoutiqueText: findInBoutique?.textContent,
  triggerRows: triggers.map(t => ({text: t.textContent, icon: iconInfo(t)})),
}, null, 2);

